import SwiftUI

struct MovieListView: View {
    @State private var viewModel: MovieListViewModel

    init(viewModel: MovieListViewModel) {
        _viewModel = State(initialValue: viewModel)
    }

    var body: some View {
        content
            .navigationTitle("Popular")
            .task { await viewModel.load() }
    }

    @ViewBuilder
    private var content: some View {
        switch viewModel.state {
        case .idle, .loading:
            ProgressView("Loading…")
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        case .empty:
            message("No movies found.", showRetry: false)
        case .failed(let text):
            message(text, showRetry: true)
        case .loaded(let movies):
            List {
                ForEach(movies) { movie in
                    MovieRowView(movie: movie)
                        .task { await viewModel.loadNextPageIfNeeded(currentItem: movie) }
                }
                if viewModel.isLoadingNextPage {
                    ProgressView().frame(maxWidth: .infinity)
                } else if let error = viewModel.paginationErrorMessage {
                    Text(error).font(.footnote).foregroundStyle(.secondary)
                }
            }
            .listStyle(.plain)
            .refreshable { await viewModel.refresh() }
        }
    }

    private func message(_ text: String, showRetry: Bool) -> some View {
        VStack(spacing: 12) {
            Text(text).multilineTextAlignment(.center).foregroundStyle(.secondary)
            if showRetry {
                Button("Try Again") { Task { await viewModel.load() } }
                    .buttonStyle(.bordered)
            }
        }
        .padding()
        .frame(maxWidth: .infinity, maxHeight: .infinity)
    }
}
